Span<nint> values = stackalloc nint[] { 1, 2, 3, 4, 5 };

Console.WriteLine($"Length: {values.Length}");
Console.WriteLine($"Element size: {sizeof(nint)} bytes");

nint sum = 0;
for (int i = 0; i < values.Length; i++)
{
    sum += values[i];
    Console.WriteLine($"  values[{i}] = {values[i]}");
}
Console.WriteLine($"Sum: {sum}");

// Also test with an empty stackalloc
Span<nint> empty = stackalloc nint[0];
Console.WriteLine($"Empty span length: {empty.Length}");

// Test with nuint too
Span<nuint> unsigned = stackalloc nuint[] { 10, 20, 30 };
